const app=express(); const port=Number(process.env.PORT)||4000; const jwtSecret=process.env.JWT_SECRET;
if(!jwtSecret&&process.env.NODE_ENV==='production') throw new Error('JWT_SECRET must be configured in production.');
app.use(helmet({contentSecurityPolicy:{directives:{defaultSrc:["'self'"],imgSrc:["'self'",'data:','blob:','https:'],mediaSrc:["'self'",'blob:','https:'],frameSrc:["'self'",'https:','https://www.youtube-nocookie.com','https://www.youtube.com','https://drive.google.com','https://player.vimeo.com','https://www.dailymotion.com','https://www.tiktok.com','https://www.instagram.com','https://www.facebook.com'],connectSrc:["'self'",'https:']}}}));app.use(cors({origin:process.env.CLIENT_ORIGIN?.split(',')||'http://localhost:5173'}));app.use(express.json({limit:'1mb'}));app.use('/api',rateLimit({windowMs:15*60*1000,limit:180,standardHeaders:true,legacyHeaders:false}));
const acceptedMediaTypes=new Set(['image/jpeg','image/png','image/webp','image/heic','image/heif','application/pdf','video/mp4','video/webm']);
const mediaUpload=multer({storage:multer.memoryStorage(),limits:{fileSize:20*1024*1024,files:20},fileFilter:(_req,file,done)=>acceptedMediaTypes.has(file.mimetype)?done(null,true):done(new Error('Upload JPG, PNG, WebP, PDF, or MP4 files.'))});
type AuthedRequest=express.Request&{user?:{id:string;role:string}};
const auth=(admin=false):express.RequestHandler=>(req:AuthedRequest,res,next)=>{try{const token=req.headers.authorization?.replace(/^Bearer\s+/i,'');if(!token) return res.status(401).json({error:'Sign in to continue.'});const payload=jwt.verify(token,jwtSecret||'local-development-secret') as {id:string;role:string};req.user=payload;if(admin){void User.findById(payload.id).select('role').then(user=>{if(!user||user.role!=='admin')return res.status(403).json({error:'Admin access required.'});req.user!.role=user.role;next()}).catch(next);return;}next()}catch{return res.status(401).json({error:'Your session has expired. Please sign in again.'})}};
const asyncRoute=(fn:express.RequestHandler):express.RequestHandler=>(req,res,next)=>Promise.resolve(fn(req,res,next)).catch(next);
const signToken=(user:{_id:unknown;role:string})=>jwt.sign({id:String(user._id),role:user.role},jwtSecret||'local-development-secret',{expiresIn:'7d'});
const account=(u:any)=>({id:String(u._id),name:u.name,email:u.email,role:u.role,avatarPreference:u.avatarPreference,interests:u.interests,createdAt:u.createdAt});
app.get('/api/health',(_req,res)=>res.json({ok:true,service:'speakora-api',database:mongoose.connection.readyState===1?'connected':'disconnected',aiProvider:process.env.OPENROUTER_API_KEY?.trim()?'openrouter':process.env.OPENAI_API_KEY?.trim()?'openai':'not-configured',aiModel:process.env.OPENROUTER_API_KEY?.trim()?(process.env.OPENROUTER_MODEL||'openai/gpt-4o-mini'):(process.env.OPENAI_MODEL||'gpt-4o-mini')}));
app.get('/api/ai/status',auth(),asyncRoute(async(_req,res)=>{const status=await checkAIConnection();res.json({...status,database:mongoose.connection.readyState===1?'connected':'disconnected'});}));
app.use('/api',(req,res,next)=>{if(mongoose.connection.readyState!==1){if(req.method==='GET'&&req.path==='/gate/questions')return next();return res.status(503).json({error:'Database unavailable. Configure MONGODB_URI and connect MongoDB to use accounts and saved question banks.'});}next()});
app.post('/api/auth/register',asyncRoute(async(req,res)=>{const body=z.object({name:z.string().trim().min(2).max(80),email:z.string().email(),password:z.string().min(8).max(100)}).parse(req.body);const email=body.email.toLowerCase();if(email===process.env.ADMIN_EMAIL?.trim().toLowerCase())return res.status(403).json({error:'Use the private admin sign-in page to access the configured administrator account.'});if(await User.exists({email}))return res.status(409).json({error:'An account with this email already exists.'});const user=await User.create({name:body.name,email,passwordHash:await bcrypt.hash(body.password,12),role:'learner'});res.status(201).json({token:signToken(user),user:account(user)});}));
app.post('/api/auth/login',asyncRoute(async(req,res)=>{const body=z.object({email:z.string().email(),password:z.string().min(1)}).parse(req.body);const email=body.email.toLowerCase();const user=await User.findOne({email});if(!user||!await bcrypt.compare(body.password,user.passwordHash))return res.status(401).json({error:'Email or password is incorrect.'});if(process.env.ADMIN_EMAIL&&email===process.env.ADMIN_EMAIL.trim().toLowerCase()&&user.role!=='admin'){user.role='admin';await user.save();}res.json({token:signToken(user),user:account(user)});}));
app.get('/api/auth/me',auth(),asyncRoute(async(req:AuthedRequest,res)=>{const user=await User.findById(req.user!.id).select('-passwordHash');if(!user)return res.status(401).json({error:'Account not found.'});if(process.env.ADMIN_EMAIL&&user.email.toLowerCase()===process.env.ADMIN_EMAIL.trim().toLowerCase()&&user.role!=='admin'){user.role='admin';await user.save();}res.json({user:account(user)});}));
app.patch('/api/profile',auth(),asyncRoute(async(req:AuthedRequest,res)=>{const body=z.object({avatarPreference:z.enum(['male','female','neutral']).optional(),interests:z.array(z.string().max(60)).max(20).optional(),name:z.string().trim().min(2).max(80).optional()}).parse(req.body);const user=await User.findByIdAndUpdate(req.user!.id,body,{new:true}).select('-passwordHash');res.json({user:account(user)});}));
const speakingIntroductionInput=z.object({name:z.string().trim().max(80).optional(),occupation:z.string().trim().max(160).optional(),studyOrProfession:z.string().trim().max(240).optional(),organization:z.string().trim().max(180).optional(),skills:z.array(z.string().trim().max(80)).max(20).optional(),hobbies:z.array(z.string().trim().max(240)).max(20).optional(),careerGoals:z.string().trim().max(500).optional(),englishGoal:z.string().trim().max(500).optional(),level:z.enum(['beginner','intermediate','advanced']).optional(),completed:z.boolean().optional()});
app.get('/api/speaking/introduction',auth(),asyncRoute(async(req:AuthedRequest,res)=>{const item=await UserIntroduction.findOne({user:req.user!.id}).lean();res.json({introduction:item||null});}));
app.put('/api/speaking/introduction',auth(),asyncRoute(async(req:AuthedRequest,res)=>{const body=speakingIntroductionInput.parse(req.body);const item:any=await UserIntroduction.findOneAndUpdate({user:req.user!.id},{$set:body,$setOnInsert:{user:req.user!.id}},{new:true,upsert:true,runValidators:true,setDefaultsOnInsert:true});if(body.completed){try{const summary=await askAI(learningGuide+' Write a friendly first-person English self-introduction for a language learner based only on the supplied profile. Use 3-5 short natural sentences, appropriate to the learner level, suitable for speaking aloud. Do not add facts the learner did not provide. Return plain text only.',JSON.stringify({name:item.name,occupation:item.occupation,studyOrProfession:item.studyOrProfession,organization:item.organization,skills:item.skills,hobbies:item.hobbies,careerGoals:item.careerGoals,englishGoal:item.englishGoal,level:item.level}));item.summary=summary.trim().slice(0,1000);await item.save();}catch{item.summary='';}}res.json({introduction:item});}));
app.post('/api/speaking/start',auth(),asyncRoute(async(req:AuthedRequest,res)=>{const fields=z.object({topic:z.string().trim().min(2).max(120),category:z.string().trim().min(2).max(80),level:z.enum(['beginner','intermediate','advanced']),style:z.enum(['friendly','professional','interviewer','discussion']).default('friendly'),avatar:z.enum(['male','female','neutral']).default('neutral')}).parse(req.body);const profile:any=await UserIntroduction.findOne({user:req.user!.id,completed:true}).lean();const config:any=await PracticePrompt.findOne({category:fields.category,status:'published'}).sort({updatedAt:-1}).select('instructions categoryDescription').lean();const recent=await SpeakingSession.find({user:req.user!.id,status:'completed'}).sort({endedAt:-1}).limit(1).select('messages.question').lean();const extra=config?.instructions?` Admin guidance for this category: ${config.instructions}`:'';const raw=await askAI(learningGuide+' Start a natural English speaking conversation with exactly one short, relevant opening question about the selected topic. Match the learner level and conversation style. If profile context is present, personalize using only its facts. Return JSON with question and brief tip.'+extra,JSON.stringify({topic:fields.topic,category:fields.category,level:fields.level,style:fields.style,profile:profile?{name:profile.name,occupation:profile.occupation,studyOrProfession:profile.studyOrProfession,skills:profile.skills,interests:profile.hobbies,goals:profile.careerGoals}:null,avoidQuestions:recent[0]?.messages?.map((m:any)=>m.question).slice(-8)||[]}),true);const generated=JSON.parse(raw);if(typeof generated.question!=='string'||!generated.question.trim())throw Object.assign(new Error('AI did not return an opening question. Please try again.'),{status:502});const session=await SpeakingSession.create({user:req.user!.id,...fields,instructions:config?.instructions||'',messages:[{question:generated.question.trim(),answer:'',createdAt:new Date()}]});res.status(201).json({session:{id:String(session._id),topic:session.topic,category:session.category,level:session.level,style:session.style,avatar:session.avatar,question:generated.question.trim(),tip:typeof generated.tip==='string'?generated.tip:''}});}));
app.get('/api/speaking/active',auth(),asyncRoute(async(req:AuthedRequest,res)=>{const session:any=await SpeakingSession.findOne({user:req.user!.id,status:'in_progress'}).sort({createdAt:-1}).lean();if(!session)return res.json({session:null});res.json({session:{id:String(session._id),topic:session.topic,category:session.category,level:session.level,style:session.style,avatar:session.avatar,messages:session.messages,startedAt:session.startedAt}});}));
app.post('/api/speaking/answer',auth(),asyncRoute(async(req:AuthedRequest,res)=>{const body=z.object({sessionId:z.string().length(24),answer:z.string().trim().min(3).max(1500)}).parse(req.body);if(!mongoose.isValidObjectId(body.sessionId))return res.status(400).json({error:'Invalid speaking session.'});const session:any=await SpeakingSession.findOne({_id:body.sessionId,user:req.user!.id,status:'in_progress'});if(!session)return res.status(404).json({error:'Active speaking session not found.'});if(session.messages.filter((m:any)=>String(m.answer||'').trim()).length>=30)return res.status(409).json({error:'This session has reached 30 answers. End it to view your report.'});const current=session.messages[session.messages.length-1];const history=session.messages.slice(-8).map((m:any)=>({question:m.question,answer:m.answer,feedback:m.feedback?{corrected:m.feedback.corrected,scores:m.feedback.scores}:undefined}));const raw=await askAI(learningGuide+' You are an encouraging live English conversation partner and coach. Evaluate the learner answer, then ask exactly one relevant follow-up question. Return JSON keys feedback (corrected, naturalVersion, professionalVersion, explanationHindi, strengths string[], mistakes array of {original,corrected,reasonHindi}, vocabularySuggestions array of {word,meaningHindi,example}, scores object with grammar, vocabulary, sentenceFormation, clarity, relevance, communication each integer 0-100), nextQuestion, nextTip. Scores must reflect this answer only; do not judge pronunciation from text. Keep corrections useful and simple. Avoid questions already asked in the conversation.'+(session.instructions?` Admin category guidance: ${session.instructions}`:''),JSON.stringify({topic:session.topic,category:session.category,level:session.level,style:session.style,conversation:history,currentQuestion:current.question,answer:body.answer}),true);const generated=JSON.parse(raw);const feedback=generated.feedback||{};const scoreKeys=['grammar','vocabulary','sentenceFormation','clarity','relevance','communication'];feedback.scores=Object.fromEntries(scoreKeys.map(key=>{const value=Number(generated.feedback?.scores?.[key]);return[key,Number.isFinite(value)?Math.max(0,Math.min(100,Math.round(value))):0]}));feedback.mistakes=Array.isArray(feedback.mistakes)?feedback.mistakes:[];feedback.vocabularySuggestions=Array.isArray(feedback.vocabularySuggestions)?feedback.vocabularySuggestions:[];feedback.strengths=Array.isArray(feedback.strengths)?feedback.strengths:[];current.answer=body.answer;current.feedback=feedback;session.messages.push({question:String(generated.nextQuestion||'What else would you like to share about this topic?').slice(0,1200),answer:'',createdAt:new Date()});await session.save();await PracticeSession.create({user:req.user!.id,kind:'speaking',input:body.answer,topic:session.topic,category:session.category,level:session.level,output:{...feedback,question:current.question,style:session.style}});res.json({feedback,nextQuestion:session.messages[session.messages.length-1].question,nextTip:typeof generated.nextTip==='string'?generated.nextTip:'',answeredCount:session.messages.filter((m:any)=>String(m.answer||'').trim()).length});}));
app.post('/api/speaking/end',auth(),asyncRoute(async(req:AuthedRequest,res)=>{const body=z.object({sessionId:z.string().length(24)}).parse(req.body);if(!mongoose.isValidObjectId(body.sessionId))return res.status(400).json({error:'Invalid speaking session.'});const session:any=await SpeakingSession.findOne({_id:body.sessionId,user:req.user!.id});if(!session)return res.status(404).json({error:'Speaking session not found.'});if(session.status==='completed')return res.json({report:session.report,sessionId:String(session._id)});const answers=session.messages.filter((m:any)=>String(m.answer||'').trim());if(!answers.length)return res.status(400).json({error:'Answer at least one question before ending the conversation.'});const scoreKeys=['grammar','vocabulary','sentenceFormation','clarity','relevance','communication'];const skillScores=Object.fromEntries(scoreKeys.map(key=>{const values=answers.map((m:any)=>Number(m.feedback?.scores?.[key])).filter(Number.isFinite);return[key,values.length?Math.round(values.reduce((a:number,b:number)=>a+b,0)/values.length):0]}));const overallScore=Math.round(scoreKeys.reduce((sum,key)=>sum+Number(skillScores[key]||0),0)/scoreKeys.length);const transcript=answers.map((m:any,i:number)=>({number:i+1,question:m.question,answer:m.answer,feedback:m.feedback}));const generated=JSON.parse(await askAI(learningGuide+' Create an actionable speaking performance report from the complete conversation. Return JSON keys strengths (string[]), weaknesses (string[]), commonMistakes (string[]), correctedSentences (string[]), betterAlternatives (string[]), professionalVocabulary (array of {word,meaningHindi,example}), nextGoals (exactly 3 strings), scoreInterpretation (string). Reference actual patterns in the answers. Do not invent audio or pronunciation evidence. Keep Hindi explanations simple.',JSON.stringify({topic:session.topic,level:session.level,style:session.style,answers:transcript,calculatedScores:skillScores,overallScore,formula:'Overall score = arithmetic mean of Grammar, Vocabulary, Sentence Formation, Clarity, Relevance, and Communication averages across answered turns.'}),true));const profile:any=await UserIntroduction.findOne({user:req.user!.id}).select('name').lean();const report={userName:profile?.name||'',topic:session.topic,category:session.category,level:session.level,style:session.style,date:new Date().toISOString(),totalQuestions:session.messages.length,totalAnswers:answers.length,durationSeconds:Math.max(0,Math.round((Date.now()-new Date(session.startedAt).getTime())/1000)),skillScores,overallScore,formula:'Overall = the arithmetic mean of the six skill scores; each skill score is the mean for that skill across answered turns.',scoreInterpretation:generated.scoreInterpretation||'',strengths:Array.isArray(generated.strengths)?generated.strengths:[],weaknesses:Array.isArray(generated.weaknesses)?generated.weaknesses:[],commonMistakes:Array.isArray(generated.commonMistakes)?generated.commonMistakes:[],correctedSentences:Array.isArray(generated.correctedSentences)?generated.correctedSentences:[],betterAlternatives:Array.isArray(generated.betterAlternatives)?generated.betterAlternatives:[],professionalVocabulary:Array.isArray(generated.professionalVocabulary)?generated.professionalVocabulary:[],nextGoals:Array.isArray(generated.nextGoals)?generated.nextGoals.slice(0,3):[],questionAnalysis:transcript};session.status='completed';session.endedAt=new Date();session.durationSeconds=report.durationSeconds;session.overallScore=overallScore;session.skillScores=skillScores;session.report=report;await session.save();res.json({report,sessionId:String(session._id)});}));
app.get('/api/speaking/reports',auth(),asyncRoute(async(req:AuthedRequest,res)=>{const [items,total]=await Promise.all([SpeakingSession.find({user:req.user!.id,status:'completed'}).sort({endedAt:-1}).limit(Math.min(100,Math.max(1,Number(req.query.limit)||30))).select('topic category level style status startedAt endedAt durationSeconds overallScore skillScores report createdAt').lean(),SpeakingSession.countDocuments({user:req.user!.id,status:'completed'})]);res.json({items,total});}));
app.get('/api/speaking/reports/:id',auth(),asyncRoute(async(req:AuthedRequest,res)=>{if(!mongoose.isValidObjectId(req.params.id))return res.status(400).json({error:'Invalid report.'});const item:any=await SpeakingSession.findOne({_id:req.params.id,user:req.user!.id,status:'completed'}).select('topic category level style startedAt endedAt durationSeconds overallScore skillScores report messages').lean();if(!item)return res.status(404).json({error:'Report not found.'});res.json({item});}));
app.get('/api/admin/speaking/analytics',auth(true),asyncRoute(async(_req,res)=>{const since=new Date(Date.now()-7*24*60*60*1000);const [summary,topics,activity]=await Promise.all([SpeakingSession.aggregate([{$match:{status:'completed'}},{$group:{_id:null,sessions:{$sum:1},averageScore:{$avg:'$overallScore'},users:{$addToSet:'$user'}}},{$project:{_id:0,sessions:1,averageScore:{$round:['$averageScore',1]},users:{$size:'$users'}}}]),SpeakingSession.aggregate([{$match:{status:'completed'}},{$group:{_id:'$category',sessions:{$sum:1},averageScore:{$avg:'$overallScore'}}},{$sort:{sessions:-1}},{$limit:8}]),SpeakingSession.aggregate([{$match:{createdAt:{$gte:since}}},{$group:{_id:{$dateToString:{format:'%Y-%m-%d',date:'$createdAt',timezone:'Asia/Kolkata'}},sessions:{$sum:1},learners:{$addToSet:'$user'}}},{$project:{_id:1,sessions:1,learners:{$size:'$learners'}}},{$sort:{_id:1}}])]);res.json({summary:summary[0]||{sessions:0,averageScore:0,users:0},topics,activity});}));
app.get('/api/speaking/history',auth(),asyncRoute(async(req:AuthedRequest,res)=>{const limit=Math.min(100,Math.max(1,Number(req.query.limit)||30));const [sessions,total]=await Promise.all([PracticeSession.find({user:req.user!.id,kind:'speaking'}).sort({createdAt:-1}).limit(limit).select('input output topic category level minutes createdAt').lean(),PracticeSession.countDocuments({user:req.user!.id,kind:'speaking'})]);res.json({sessions,total});}));
app.get('/api/admin/users',auth(true),asyncRoute(async(req:AuthedRequest,res)=>{const q=String(req.query.q||'').trim().slice(0,100);const page=Math.max(1,Number(req.query.page)||1);const limit=Math.min(100,Math.max(1,Number(req.query.limit)||50));const filter:any={};if(q){const escaped=q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');filter.$or=[{name:{$regex:escaped,$options:'i'}},{email:{$regex:escaped,$options:'i'}}];}const [users,filteredTotal,total,learners,admins]=await Promise.all([User.find(filter).select('name email role createdAt updatedAt').sort({createdAt:-1}).skip((page-1)*limit).limit(limit).lean(),User.countDocuments(filter),User.countDocuments({}),User.countDocuments({role:'learner'}),User.countDocuments({role:'admin'})]);res.json({items:users.map((user:any)=>account(user)),total,filteredTotal,learners,admins,page,pages:Math.max(1,Math.ceil(filteredTotal/limit))});}));
app.patch('/api/admin/users/:id',auth(true),asyncRoute(async(req:AuthedRequest,res)=>{if(!mongoose.isValidObjectId(req.params.id))return res.status(400).json({error:'Invalid account.'});if(req.params.id===req.user!.id)return res.status(400).json({error:'Use profile settings to update your own account.'});const body=z.object({name:z.string().trim().min(2).max(80),email:z.string().trim().email().max(254)}).parse(req.body);const email=body.email.toLowerCase();if(email===process.env.ADMIN_EMAIL?.trim().toLowerCase())return res.status(409).json({error:'This email is reserved for the configured administrator.'});const user=await User.findOne({_id:req.params.id,role:'learner'});if(!user)return res.status(404).json({error:'Learner account not found.'});const existing=await User.exists({email,_id:{$ne:user._id}});if(existing)return res.status(409).json({error:'That email address is already in use.'});user.name=body.name;user.email=email;await user.save();res.json({user:account(user)});}));
app.post('/api/admin/users/:id/password',auth(true),asyncRoute(async(req:AuthedRequest,res)=>{if(!mongoose.isValidObjectId(req.params.id))return res.status(400).json({error:'Invalid account.'});const body=z.object({password:z.string().min(8).max(100)}).parse(req.body);const user=await User.findOne({_id:req.params.id,role:'learner'});if(!user)return res.status(404).json({error:'Learner account not found.'});user.passwordHash=await bcrypt.hash(body.password,12);await user.save();res.json({ok:true});}));

app.delete('/api/admin/users/:id',auth(true),asyncRoute(async(req:AuthedRequest,res)=>{if(!mongoose.isValidObjectId(req.params.id))return res.status(400).json({error:'Invalid account.'});if(req.params.id===req.user!.id)return res.status(400).json({error:'You cannot delete the signed-in admin account.'});const user=await User.findOneAndDelete({_id:req.params.id,role:'learner'});if(!user)return res.status(404).json({error:'Learner account not found.'});await Promise.all([PracticeSession.deleteMany({user:user._id}),SpeakingSession.deleteMany({user:user._id}),UserIntroduction.deleteOne({user:user._id})]);res.json({ok:true});}));
app.get('/api/topics',asyncRoute(async(req,res)=>{const query:any={status:'published'};if(req.query.category)query.category=req.query.category;if(req.query.difficulty)query.difficulty=req.query.difficulty;const page=Math.max(1,Number(req.query.page)||1);const limit=Math.min(30,Math.max(1,Number(req.query.limit)||12));const [items,total]=await Promise.all([Topic.find(query).sort({publishedAt:-1}).skip((page-1)*limit).limit(limit).lean(),Topic.countDocuments(query)]);res.json({items,total,page,pages:Math.ceil(total/limit)});}));
