app.get('/api/vocabulary',asyncRoute(async(req,res)=>{const query:any={status:'published'};if(req.query.category)query.category=req.query.category;if(req.query.q)query.word={$regex:String(req.query.q).slice(0,50),$options:'i'};const page=Math.max(1,Number(req.query.page)||1);const limit=Math.min(250,Math.max(1,Number(req.query.limit)||20));const [items,total]=await Promise.all([Vocabulary.find(query).sort({word:1}).skip((page-1)*limit).limit(limit).lean(),Vocabulary.countDocuments(query)]);res.json({items,total,page,pages:Math.ceil(total/limit)});}));
