app.post('/api/admin/vocabulary/generate',auth(true),asyncRoute(async(req,res)=>{const input=z.object({word:z.string().trim().min(1).max(100),category:z.string().trim().min(2).max(80),difficulty:z.enum(['beginner','intermediate','advanced']).default('beginner')}).parse(req.body);const generated=JSON.parse(await askAI(learningGuide+' Create one accurate English vocabulary entry for a Hindi-speaking learner. Return JSON only with keys: word, meaningHindi, definition, partOfSpeech, pronunciation, example, translationHindi, whereToUse, whereNotToUse. Keep the definition and example clear and age-appropriate; pronunciation should be simple phonetic guidance, not IPA unless helpful.',`Create an entry for the word or phrase "${input.word}" in the category "${input.category}" for a ${input.difficulty} learner.`,true));const draft=z.object({word:z.string().min(1).max(100),meaningHindi:z.string().max(250),definition:z.string().max(1200),partOfSpeech:z.string().max(30),pronunciation:z.string().max(100),example:z.string().max(1000),translationHindi:z.string().max(1000),whereToUse:z.string().max(1000),whereNotToUse:z.string().max(1000)}).parse(generated);res.json({draft:{...draft,category:input.category,difficulty:input.difficulty,status:'draft'}});}));
