app.post('/api/learn/speaking-prompt',auth(),asyncRoute(async(req:AuthedRequest,res)=>{const {topic,previous,category,level}=z.object({topic:z.string().max(120).default('daily life'),previous:z.string().max(1200).optional(),category:z.string().max(80).default('Daily Life'),level:z.enum(['beginner','intermediate','advanced']).default('beginner')}).parse(req.body);const profile:any=await UserIntroduction.findOne({user:req.user!.id}).lean();const profileContext=profile?JSON.stringify({name:profile.name,role:profile.occupation,studyOrProfession:profile.studyOrProfession,organization:profile.organization,skills:profile.skills,hobbies:profile.hobbies,careerGoals:profile.careerGoals,englishGoal:profile.englishGoal,level:profile.level}):'No personal profile provided; ask broadly relevant questions.';const recent=await PracticeSession.find({user:req.user!.id,kind:'speaking'}).sort({createdAt:-1}).limit(5).select('input output category').lean();const conversation=recent.reverse().map((session:any)=>({category:session.category,answer:String(session.input||'').slice(0,700),correction:String(session.output?.corrected||'').slice(0,700)}));const raw=await askAI(learningGuide+' Create exactly one practical, personalized speaking question based on the learner profile and category. Ask one question only, be specific to their actual studies, job, skills, hobbies or goals when relevant, and avoid repeating prior questions. Build a natural follow-up from recent answers when appropriate. Return JSON with question, sampleAnswer, and tip. Use clear English suitable for the level; never invent profile facts.',`Learner profile: ${profileContext}. Category: ${category}. Topic: ${topic}. Level: ${profile?.level||level}. Recent conversation: ${JSON.stringify(conversation)}. Most recent answer or topic to build on: ${previous||'none'}`,true);const result=JSON.parse(raw);res.json({prompt:result.question,sample:result.sampleAnswer,tip:result.tip});}));
app.post('/api/learn/speaking-live-feedback',auth(),asyncRoute(async(req,res)=>{const {text,previousText,category,level}=z.object({text:z.string().trim().min(3).max(1500),previousText:z.string().max(1500).default(''),category:z.string().max(80).default('Daily Life'),level:z.enum(['beginner','intermediate','advanced']).default('beginner')}).parse(req.body);const raw=await askAI(learningGuide+' Act as a real-time English speaking coach. Compare the latest speech with previously reviewed speech and report only NEW, useful errors in the latest sentence; do not repeat already-reported corrections. Be kind and do not mark acceptable conversational English as wrong. Return JSON keys: mistakes (array of {original, corrected, reasonHindi, type}), immediateTip (one brief encouraging suggestion; empty string if none). Keep at most 4 mistakes.',`Category: ${category}; level: ${level}. Previously reviewed transcript: ${previousText||'(none)'}. Current complete transcript: ${text}. Identify mistakes in only the newest sentence/phrase.`,true);const result=JSON.parse(raw);res.json({mistakes:Array.isArray(result.mistakes)?result.mistakes.slice(0,4):[],immediateTip:typeof result.immediateTip==='string'?result.immediateTip:''});}));
app.post('/api/learn/correct',auth(),asyncRoute(async(req:AuthedRequest,res)=>{const {text,topic,category,level}=z.object({text:z.string().trim().min(2).max(1500),topic:z.string().max(120).default('Speaking practice'),category:z.string().max(80).default('Daily Life'),level:z.enum(['beginner','intermediate','advanced']).default('beginner')}).parse(req.body);const raw=await askAI(learningGuide+' Evaluate this speech transcript fairly at the stated level. Return valid JSON with keys corrected, naturalVersion (clear natural spoken English), relevance (brief note on how directly it answers the prompt), encouragement, explanationHindi, tryAgain, professionalVersion, strengths (array of strings), mistakes (array of {original, corrected, reasonHindi, type} covering every meaningful grammar, word-choice, sentence-formation, clarity or transcription issue apparent in the transcript; do not infer pronunciation from text), vocabularySuggestions (array of {word, meaningHindi, example}), and scores (object with grammar, vocabulary, sentenceFormation, fluency, clarity, communication each integer 0-100). If there are no clear errors, return an empty mistakes array. Score only evidence in the answer; fluency must be labeled an estimate from text indicators and not an audio measurement. Be supportive and concise.',`Category: ${category}. Topic: ${topic}. Level: ${level}. Full spoken answer: ${text}`,true);const result=JSON.parse(raw);const scoreKeys=['grammar','vocabulary','sentenceFormation','fluency','clarity','communication'];if(result.scores&&typeof result.scores==='object')for(const key of scoreKeys){const value=Number(result.scores[key]);result.scores[key]=Number.isFinite(value)?Math.max(0,Math.min(100,Math.round(value))):0;}else result.scores=Object.fromEntries(scoreKeys.map(key=>[key,0]));result.naturalVersion=typeof result.naturalVersion==='string'?result.naturalVersion:result.corrected;result.relevance=typeof result.relevance==='string'?result.relevance:'';result.strengths=Array.isArray(result.strengths)?result.strengths:[];result.mistakes=Array.isArray(result.mistakes)?result.mistakes:[];result.vocabularySuggestions=Array.isArray(result.vocabularySuggestions)?result.vocabularySuggestions:[];await PracticeSession.create({user:req.user!.id,kind:'speaking',input:text,output:{...result,topic,category,level}});res.json({result});}));
