app.post('/api/admin/media/sync',auth(true),asyncRoute(async(req:AuthedRequest,res)=>{const config=cloudinary.config();if(!config.cloud_name||!config.api_key||!config.api_secret)return res.status(503).json({error:'Cloudinary is not configured. Set CLOUDINARY_URL on the server.'});const resources=await Promise.all((['image','video','raw'] as const).map(resource_type=>cloudinary.api.resources({resource_type,type:'upload',prefix:'speakora/learning/',max_results:100})));const assets=resources.flatMap((batch:any)=>batch.resources||[]);const ids=assets.map((asset:any)=>asset.public_id);const existing=await MediaAsset.find({publicId:{$in:ids}}).select('publicId').lean();const known=new Set(existing.map((item:any)=>item.publicId));const fresh=assets.filter((asset:any)=>!known.has(asset.public_id));if(!fresh.length)return res.json({created:0,skipped:assets.length});const docs=fresh.map((asset:any)=>({title:String(asset.public_id.split('/').pop()||'Learning resource').replace(/[_-]+/g,' '),description:'',category:'Learning media',url:asset.secure_url,publicId:asset.public_id,resourceType:asset.resource_type,format:asset.format,bytes:asset.bytes,status:'published',createdBy:req.user!.id,updatedBy:req.user!.id}));const items=await MediaAsset.insertMany(docs,{ordered:false});res.json({created:items.length,skipped:assets.length-items.length});}));
app.post('/api/admin/media',auth(true),mediaUpload.array('files',20),asyncRoute(async(req:AuthedRequest,res)=>{const files=(req.files as Express.Multer.File[]|undefined)||[];if(!files.length)return res.status(400).json({error:'Choose one or more media files to upload.'});const fields=z.object({title:z.string().trim().min(2).max(120),category:z.string().trim().min(2).max(80),description:z.string().trim().max(2000).optional().default(''),status:z.enum(['draft','published','archived']).default('draft')}).parse(req.body);const config=cloudinary.config();if(!config.cloud_name||!config.api_key||!config.api_secret)return res.status(503).json({error:'Cloudinary is not configured. Set CLOUDINARY_URL on the server.'});const uploaded=await Promise.all(files.map(async(file,index)=>{try{const result:any=await new Promise((resolve,reject)=>{const stream=cloudinary.uploader.upload_stream({folder:'speakora/learning',resource_type:'auto',use_filename:true,unique_filename:true},(error,data)=>error?reject(error):resolve(data));stream.end(file.buffer)});const namedTitle=files.length===1?fields.title:`${fields.title} ${index+1}`;const item=await MediaAsset.create({...fields,title:namedTitle,url:result.secure_url,publicId:result.public_id,resourceType:result.resource_type,format:result.format,bytes:result.bytes,createdBy:req.user!.id,updatedBy:req.user!.id});return{item};}catch(error:any){return{error:{file:file.originalname,message:error.message||'Upload failed.'}}}}));const items=uploaded.flatMap(result=>'item'in result?[result.item]:[]);const errors=uploaded.flatMap(result=>'error'in result?[result.error]:[]);if(!items.length)return res.status(502).json({error:errors[0]?.message||'No files could be uploaded.',items:[],errors});res.status(errors.length?207:201).json({items,errors});}));
app.post('/api/admin/media/link',auth(true),asyncRoute(async(req:AuthedRequest,res)=>{const fields=z.object({title:z.string().trim().min(2).max(120),category:z.string().trim().min(2).max(80),description:z.string().trim().max(2000).optional().default(''),url:z.string().url().max(2000),status:z.enum(['draft','published','archived']).default('published')}).parse(req.body);const link=new URL(fields.url);if(link.protocol!=='https:'||link.username||link.password)return res.status(400).json({error:'Please provide a public HTTPS sharing link.'});const host=link.hostname.toLowerCase();let provider='External link';let embedUrl='';let resourceType:'image'|'video'|'raw'='raw';const videoHosts=['youtube.com','www.youtube.com','m.youtube.com','youtu.be'];if(videoHosts.includes(host)){const id=host==='youtu.be'?link.pathname.split('/').filter(Boolean)[0]:link.searchParams.get('v')||link.pathname.match(/\/(?:embed|shorts|live)\/([\w-]{11})/)?.[1];if(id&&/^[\w-]{11}$/.test(id)){provider='YouTube';embedUrl=`https://www.youtube-nocookie.com/embed/${id}?rel=0`;resourceType='video';}}else if(host==='drive.google.com'||host==='docs.google.com'){const id=link.pathname.match(/\/(?:file|document|spreadsheets|presentation)\/d\/([\w-]+)/)?.[1]||link.searchParams.get('id');provider='Google Drive';if(id){embedUrl=`https://drive.google.com/file/d/${encodeURIComponent(id)}/preview`;resourceType='raw';}}else{const platforms:[string,string][]=[['instagram.com','Instagram'],['tiktok.com','TikTok'],['facebook.com','Facebook'],['fb.watch','Facebook'],['x.com','X'],['twitter.com','X'],['linkedin.com','LinkedIn'],['vimeo.com','Vimeo'],['twitch.tv','Twitch'],['dailymotion.com','Dailymotion'],['reddit.com','Reddit'],['pinterest.com','Pinterest'],['threads.net','Threads'],['snapchat.com','Snapchat']];provider=platforms.find(([domain])=>host===domain||host.endsWith(`.${domain}`))?.[1]||provider;if(/\.(?:jpe?g|png|webp|gif|avif)(?:$|\?)/i.test(link.href)){resourceType='image';provider=provider==='External link'?'Image link':provider;}else if(/\.(?:mp4|webm|mov)(?:$|\?)/i.test(link.href)){resourceType='video';provider=provider==='External link'?'Video link':provider;}}const item=await MediaAsset.create({...fields,sourceType:'external',externalProvider:provider,embedUrl,url:link.href,publicId:`external:${new mongoose.Types.ObjectId().toString()}`,resourceType,format:resourceType==='image'?'IMAGE':resourceType==='video'?'MP4':'LINK',createdBy:req.user!.id,updatedBy:req.user!.id});res.status(201).json({item});}));
