app.get('/api/gate/questions',asyncRoute(async(req,res)=>{
  const query:any={status:'published'};
  if(req.query.year){const year=Number(req.query.year);if(!Number.isInteger(year)||year<2009||year>2026)return res.status(400).json({error:'Year must be between 2009 and 2026.'});query.year=year;}
  if(req.query.subject&&req.query.subject!=='all'){const subject=String(req.query.subject).trim().toUpperCase();if(!/^(GA|AE|AG|AR|BM|BT|CE|CH|CS|CY|DA|EC|EE|ES|EY|GE|GG|IN|MA|ME|MN|MT|NM|PE|PH|PI|ST|TF|XE|XH|XL)$/.test(subject))return res.status(400).json({error:'Unknown GATE paper code.'});query.subject=req.query.section==='GA'?'GA':subject==='GA'?subject:{$in:[subject,'GA']};}
  if(req.query.section==='GA')query.section='GA';if(req.query.section==='subject')query.section='subject';if(req.query.topic)query.topic={$regex:String(req.query.topic).slice(0,80),$options:'i'};
  const page=Math.max(1,Number(req.query.page)||1);const limit=Math.min(50,Math.max(1,Number(req.query.limit)||20));
  if(mongoose.connection.readyState!==1)return res.status(503).json({error:'Database unavailable. Configure MONGODB_URI to load the saved GATE question bank.'});
  const pipeline:any[]=[{$match:query},{$sort:{year:-1,subject:1,createdAt:1,_id:1}},{$group:{_id:{year:'$year',subject:'$subject',section:'$section',topic:{$toLower:{$trim:{input:'$topic'}}},prompt:{$toLower:{$trim:{input:'$prompt'}}},answer:{$toUpper:{$trim:{input:'$answer'}}}},question:{$first:'$$ROOT'}}},{$replaceRoot:{newRoot:'$question'}}];
  const [items,count]=await Promise.all([GateQuestion.aggregate([...pipeline,{$sort:{year:-1,subject:1,topic:1,_id:1}},{$skip:(page-1)*limit},{$limit:limit},{$project:{answer:0,solution:0}}]),GateQuestion.aggregate([...pipeline,{$count:'total'}])]);
  const total=count[0]?.total||0;res.json({items,total,page,pages:Math.ceil(total/limit)});
}));
app.get('/api/gate/questions/:id/solution',asyncRoute(async(req,res)=>{const item=await GateQuestion.findOne({_id:req.params.id,status:'published'}).select('answer solution type marks negativeMarking sourceLabel sourceUrl').lean();if(!item)return res.status(404).json({error:'Question not found.'});res.json({solution:item});}));
app.get('/api/admin/gate/questions',auth(true),asyncRoute(async(req,res)=>{const query:any={};if(req.query.status)query.status=req.query.status;if(req.query.year)query.year=Number(req.query.year);if(req.query.subject)query.subject=String(req.query.subject).toUpperCase();const items=await GateQuestion.find(query).sort({year:-1,subject:1,createdAt:-1}).limit(200).lean();res.json({items});}));
app.post('/api/admin/gate/questions',auth(true),asyncRoute(async(req:AuthedRequest,res)=>{const body=gateQuestionInput.parse(req.body);if(body.section==='GA'&&body.subject!=='GA')return res.status(400).json({error:'General Aptitude questions must use the GA paper code.'});if(body.type==='MCQ'&&body.options.length<2)return res.status(400).json({error:'MCQ questions need at least two options.'});const item=await GateQuestion.create({...body,createdBy:req.user!.id,updatedBy:req.user!.id});res.status(201).json({item});}));
app.post('/api/admin/gate/questions/import',auth(true),asyncRoute(async(req:AuthedRequest,res)=>{const batch=z.object({questions:z.array(gateQuestionInput).min(1).max(250)}).parse(req.body);if(batch.questions.some(q=>(q.section==='GA'&&q.subject!=='GA')||(q.type==='MCQ'&&q.options.length<2)))return res.status(400).json({error:'Check the imported questions: GA questions must use subject GA, and MCQs need at least two answer choices.'});const years=[...new Set(batch.questions.map(q=>q.year))],subjects=[...new Set(batch.questions.map(q=>q.subject))];const existing=await GateQuestion.find({year:{$in:years},subject:{$in:subjects}}).select('year subject section topic prompt answer').lean();const seen=new Set(existing.map(questionIdentity));const fresh=batch.questions.filter(q=>{const key=questionIdentity(q);if(seen.has(key))return false;seen.add(key);return true;});const skippedDuplicates=batch.questions.length-fresh.length;if(!fresh.length)return res.status(201).json({created:0,skippedDuplicates,items:[]});const docs=fresh.map(q=>({...q,createdBy:req.user!.id,updatedBy:req.user!.id}));const items=await GateQuestion.insertMany(docs,{ordered:false});res.status(201).json({created:items.length,skippedDuplicates,items});}));
app.patch('/api/admin/gate/questions/:id',auth(true),asyncRoute(async(req:AuthedRequest,res)=>{const body=gateQuestionInput.partial().parse(req.body);const item=await GateQuestion.findByIdAndUpdate(req.params.id,{...body,updatedBy:req.user!.id},{new:true,runValidators:true});if(!item)return res.status(404).json({error:'Question not found.'});res.json({item});}));
app.delete('/api/admin/gate/questions/:id',auth(true),asyncRoute(async(req,res)=>{const item=await GateQuestion.findByIdAndDelete(req.params.id);if(!item)return res.status(404).json({error:'Question not found.'});res.json({ok:true});}));
app.use((err:any,_req:express.Request,res:express.Response,_next:express.NextFunction)=>{if(err instanceof z.ZodError)return res.status(400).json({error:'Please check the submitted fields.',details:err.flatten()});if(err instanceof multer.MulterError)return res.status(400).json({error:err.code==='LIMIT_FILE_SIZE'?'Files must be 20 MB or smaller.':'The upload was rejected.'});if(err.message==='Upload a JPG, PNG, WebP, PDF, or MP4 file.')return res.status(400).json({error:err.message});const status=err.status||500;res.status(status).json({error:status<500?err.message:'Something went wrong. Please try again.'});});
async function seedStarterVocabulary(){const existing=await Vocabulary.find({word:{$in:vocabularyStarter.map(item=>item.word)}}).select('word').lean();const seen=new Set(existing.map(item=>item.word.toLocaleLowerCase()));const missing=vocabularyStarter.filter(item=>!seen.has(item.word.toLocaleLowerCase()));if(missing.length){await Vocabulary.insertMany(missing.map(item=>({...item,title:item.word})),{ordered:false});console.log(`Added ${missing.length} starter vocabulary words.`)}else console.log('Starter vocabulary is already present.');const migrations:any=mongoose.connection.collection('speakora_migrations');const migrationId='starter-vocabulary-publish-v2';if(!await migrations.findOne({_id:migrationId})){const result=await Vocabulary.updateMany({word:{$in:vocabularyStarter.map(item=>item.word)},status:'draft'},{$set:{status:'published',publishedAt:new Date()}});await migrations.updateOne({_id:migrationId},{$setOnInsert:{appliedAt:new Date(),published:result.modifiedCount}},{upsert:true});console.log(`Published ${result.modifiedCount} starter vocabulary words for learners.`)}}
async function start(){if(process.env.MONGODB_URI){await mongoose.connect(process.env.MONGODB_URI);try{await seedStarterVocabulary()}catch(error){console.error('Could not seed starter vocabulary:',error)}}app.listen(port,()=>console.log(`Speakora API listening on ${port}`));}
start().catch(error=>{console.error('API startup failed:',error);process.exit(1)});
